-- PostgreSQL / Supabase. Neue Importtabelle; kein Zugriff auf bestehende App-Tabellen.
BEGIN;
CREATE TABLE IF NOT EXISTS public.a_plus_1_vocabulary_import (
  id text PRIMARY KEY,
  unit integer NOT NULL CHECK (unit BETWEEN 1 AND 8),
  volet integer,
  section_type text NOT NULL CHECK (section_type IN ('unit', 'module')),
  module_number integer,
  french text NOT NULL,
  german text NOT NULL,
  french_forms jsonb NOT NULL,
  proper_name boolean NOT NULL DEFAULT false,
  source_page integer NOT NULL,
  source_image text NOT NULL,
  review_status text NOT NULL,
  notes text NOT NULL DEFAULT ''
);
CREATE INDEX IF NOT EXISTS a_plus_1_vocabulary_unit_idx
ON public.a_plus_1_vocabulary_import (unit, section_type, volet);
ON CONFLICT (id) DO UPDATE SET
  unit = EXCLUDED.unit,
  volet = EXCLUDED.volet,
  section_type = EXCLUDED.section_type,
  module_number = EXCLUDED.module_number,
  french = EXCLUDED.french,
  german = EXCLUDED.german,
  french_forms = EXCLUDED.french_forms,
  proper_name = EXCLUDED.proper_name,
  source_page = EXCLUDED.source_page,
  source_image = EXCLUDED.source_image,
  review_status = EXCLUDED.review_status,
  notes = EXCLUDED.notes;
COMMIT;
